  sms_history_pending: "Some texts could not be copied yet",
  sms_history_captured_footer: "Copied texts sync when your phone is connected.",
  sms_history_capacity_footer: "Older texts stopped copying because the message history limit was reached. Texts on your phone are not affected.",
  sms_capture_enabled_label: "Enable SMS sync",
  sms_capture_disabled_hint: "Turning this off pauses new SMS capture and new sends. It does not cancel messages already handed to Android or discard pending requests and uncertain outcomes.",
  mms_capture_disclosure: "Peppy encrypts downloaded MMS, including existing history, for sync through your configured server to your authorized vault devices. This includes message content, media and group-recipient data. Using permissions already granted, Peppy may read your SIM phone number even if MMS capture is off. Peppy syncs an encrypted copy for group-recipient matching. You can enter the number manually if unavailable. Carrier MMS itself is not end-to-end encrypted.",
